'use strict';

/**
 * Module 1 / Module 8 — the alert stream.
 *
 * Alerts are generated by services, never created through the API, so this
 * controller deliberately offers no `create` handler — only list, read,
 * acknowledge and resolve.
 */

const { Alert } = require('../models');
const asyncHandler = require('../middleware/asyncHandler');
const { ok } = require('../utils/response');
const ApiError = require('../utils/ApiError');
const { parsePagination, parseSort, buildFilter, buildMeta } = require('../utils/query');
const { normaliseId } = require('./crud.factory');

/** GET /api/alerts */
const list = asyncHandler(async (req, res) => {
  const { page, limit, skip } = parsePagination(req.query);
  const sort = parseSort(req.query.sort, { createdAt: -1 });
  const filter = buildFilter(req.query, {
    allowed: ['status', 'severity', 'source', 'park', 'module'],
    searchable: ['title', 'message'],
  });

  const [items, total, activeBySeverity] = await Promise.all([
    Alert.find(filter).sort(sort).skip(skip).limit(limit).populate('park', 'name slug').lean(),
    Alert.countDocuments(filter),
    Alert.aggregate([
      { $match: { status: 'active' } },
      { $group: { _id: '$severity', count: { $sum: 1 } } },
    ]),
  ]);

  return ok(res, items.map(normaliseId), {
    ...buildMeta(total, { page, limit }),
    activeBySeverity: Object.fromEntries(activeBySeverity.map((s) => [s._id, s.count])),
  });
});

/** GET /api/alerts/:id */
const getOne = asyncHandler(async (req, res) => {
  const alert = await Alert.findById(req.params.id).populate('park', 'name slug');
  if (!alert) throw ApiError.notFound('Alert');
  return ok(res, alert);
});

/** POST /api/alerts/:id/acknowledge */
const acknowledge = asyncHandler(async (req, res) => {
  const alert = await Alert.findById(req.params.id);
  if (!alert) throw ApiError.notFound('Alert');
  if (alert.status === 'resolved') throw ApiError.badRequest('This alert is already resolved');

  alert.status = 'acknowledged';
  alert.acknowledgedBy = req.user._id;
  alert.acknowledgedAt = new Date();
  await alert.save();

  return ok(res, alert);
});

/** POST /api/alerts/:id/resolve */
const resolve = asyncHandler(async (req, res) => {
  const alert = await Alert.findById(req.params.id);
  if (!alert) throw ApiError.notFound('Alert');

  alert.status = 'resolved';
  alert.resolvedAt = new Date();
  if (!alert.acknowledgedBy) {
    alert.acknowledgedBy = req.user._id;
    alert.acknowledgedAt = new Date();
  }
  await alert.save();

  return ok(res, alert);
});

/** POST /api/alerts/acknowledge-all — clear the board in one action. */
const acknowledgeAll = asyncHandler(async (req, res) => {
  const filter = { status: 'active' };
  if (req.body.park) filter.park = req.body.park;
  if (req.body.severity) filter.severity = req.body.severity;

  const result = await Alert.updateMany(filter, {
    $set: { status: 'acknowledged', acknowledgedBy: req.user._id, acknowledgedAt: new Date() },
  });

  return ok(res, { acknowledged: result.modifiedCount });
});

module.exports = { list, getOne, acknowledge, resolve, acknowledgeAll };
